import ast

def flatten_nested_list(nested_list_string):
    """
    Flattens a nested list represented as a string.

    Args:
        nested_list_string: A string representing a nested list in Python list syntax.

    Returns:
        A string representing the flattened list in Python list syntax.
    """
    try:
        nested_list = ast.literal_eval(nested_list_string)
    except (SyntaxError, ValueError):
        return "Invalid input"

    flattened_list = []
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                flatten(item)
            else:
                flattened_list.append(item)

    flatten(nested_list)
    return str(flattened_list)

if __name__ == "__main__":
    nested_list_string = input()
    flattened_list_string = flatten_nested_list(nested_list_string)
    print(flattened_list_string)
